  mali: { skin: '#5e3a22', hair: '#120d0a' },
  lakota: { skin: '#a8683a', hair: '#141012' },
  ottoman: { skin: '#dcae82', hair: '#1c1410' },
  maya: { skin: '#b06a3c', hair: '#120e0c' },
  korea: { skin: '#e8c8a0', hair: '#141214' },
  khmer: { skin: '#b8763c', hair: '#141010' },
  swahili: { skin: '#6a4028', hair: '#120c08' },
  tibet: { skin: '#c9905a', hair: '#141010' },
  carthage: { skin: '#c99260', hair: '#1a120c' },
  byzantium: { skin: '#e2b88c', hair: '#2a1a10' },
  arabia: { skin: '#c48c58', hair: '#140e0a' },
  rus: { skin: '#f0caa6', hair: '#8a5a2a' },
  vietnam: { skin: '#d8a874', hair: '#100c0c' },
  babylon: { skin: '#c99060', hair: '#120c08' },
  nubia: { skin: '#5a3820', hair: '#100a06' },
  majapahit: { skin: '#b87a48', hair: '#120c0a' },
  spain: { skin: '#e2b48a', hair: '#2a1a10' },
  haudenosaunee: { skin: '#b07648', hair: '#100c0a' },
  assyria: { skin: '#c99060', hair: '#140c08' },
  poland: { skin: '#f0caa6', hair: '#6a4a2a' },
  scotland: { skin: '#f0c8a8', hair: '#b5541f' },
  england: { skin: '#f0c8a0', hair: '#5a3a1a' },
  france: { skin: '#ecc49c', hair: '#4a2a14' },
  germany: { skin: '#f0caa6', hair: '#7a5a2a' },
  sweden: { skin: '#f2d0b0', hair: '#d9b441' },
  portugal: { skin: '#dcae82', hair: '#2a1a10' },
