  kongo: { skin: '#5e3a22', hair: '#0e0a08' },
  ashanti: { skin: '#5a3820', hair: '#0e0a08' },
  mapuche: { skin: '#b07648', hair: '#100c0a' },
  georgia: { skin: '#e2b88c', hair: '#1a120c' },
