        ellipse(ctx, x - 1 * k, top - 0.6 * k, 5.8 * k, 3.2 * k, '#8a6a4a');
        box(ctx, x - 3.6 * k, top - 2.2 * k, 2.2 * k, 2.6 * k, '#8a6a4a');
        box(ctx, x + 2.6 * k, top - 1.4 * k, 2.2 * k, 2.6 * k, '#8a6a4a');
